        self.big.setFixedSize(92, 150)
        wv.addWidget(self.big, 0, Qt.AlignmentFlag.AlignHCenter)
        self.l_hi = lab("", "")
        self.l_hi.setStyleSheet("font-size:17px;font-weight:800;")
